add_filter( 'woocommerce_cart_shipping_packages', 'perfectpixel_split_cart_packages' );

function perfectpixel_split_cart_packages( $packages ) {
	if ( empty( $packages[0]['contents'] ) ) {
		return $packages;
	}
	$classes = array_filter( array_map( 'trim', explode( ',', '{{split_shipping_classes}}' ) ) );
	$base    = $packages[0];
	$groups  = array( '' => array() );

	foreach ( $base['contents'] as $key => $item ) {
		$class = $item['data']->get_shipping_class();
		$group = in_array( $class, $classes, true ) ? $class : '';
		$groups[ $group ][ $key ] = $item;
	}

	$split = array();
	foreach ( $groups as $contents ) {
		if ( ! $contents ) {
			continue;
		}
		$package                  = $base;
		$package['contents']      = $contents;
		$package['contents_cost'] = array_sum( wp_list_pluck( $contents, 'line_total' ) );
		$split[]                  = $package;
	}
	return $split ? $split : $packages;
}
